window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-8b6f8e77d1c78ae9"]={"versions": [{"id": "FIG-8b6f8e77d1c78ae9", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Prozessstruktur- und Dekompositionsdiagramm im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm modelliert die Dekomposition der zusammengesetzten Methodik-Aktivität (Activity) „Do Post Build Loadable Configuration“ in ihre untergeordneten Teilschritte sowie die Zuordnung zweier methodischer Realisierungsansätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Zentrum steht das zusammengesetzte Aktivitätselement (Activity) „Do Post Build Loadable Configuration“ (dargestellt als abgerundetes Symbol mit Binnen-Piktogrammen). Über Aggregationsbeziehungen mit dem Stereotyp <code>«nesting»</code> (offene Raute an der übergeordneten Aktivität) sind sechs spezifische Prozessaktivitäten (als Blockpfeile nach rechts dargestellt) eingebettet:</p>\n<ul class=\"fig-list\"><li>„Generate BSW Postbuild Configuration Code“\n</li><li>„Compile BSW Configuration Data“\n</li><li>„Link ECU Code during Post-Build Time Loadable“\n</li><li>„Generate BSW Configuration Data Loadable“\n</li><li>„Generate ...“ (am unteren rechten Rand)\n</li><li>„Compile Unconfigured ...“ (am unteren linken Rand)\n</li></ul>\n<p class=\"fig-p\">Zusätzlich sind zwei Notiz-/Kommentarelemente (Note-Symbole mit umgeknickter Ecke) über gestrichelte Verbindungslinien angebunden:</p>\n<ul class=\"fig-list\"><li>„Approach 1: Generate C code“ (zugeordnet zu „Generate BSW Postbuild Configuration Code“)\n</li><li>„Approach 2: Generate loadable data“ (zugeordnet zu „Generate BSW Configuration Data Loadable“)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schachtelungs- und Strukturhierarchie (Nesting) dar, keine zeitliche Kontrollfluss-Sequenz. Es verdeutlicht zwei alternative bzw. komplementäre Pfade zur Handhabung ladbarer Post-Build-Konfigurationsdaten:</p>\n<ol class=\"fig-list\"><li>Ansatz 1 („Approach 1: Generate C code“): Generierung von C-Quellcode für die Post-Build-Konfiguration („Generate BSW Postbuild Configuration Code“), gefolgt von Kompilierung („Compile BSW Configuration Data“) und Linken zur Post-Build-Zeit („Link ECU Code during Post-Build Time Loadable“).\n</li><li>Ansatz 2 („Approach 2: Generate loadable data“): Direkte Generierung ladbarer Binärdaten („Generate BSW Configuration Data Loadable“), die ohne Neukompilierung des Rumpfcodes in das Steuergerät geladen werden können.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Integratoren und BSW-Tool-Entwickler definiert das Diagramm die methodischen Gestaltungsoptionen für den Post-Build-Loadable-Mechanismus gemäß AUTOSAR-Standard:</p>\n<ul class=\"fig-list\"><li>Trennung zwischen quellcodebasierter Post-Build-Erzeugung (Approach 1) und rein datenbasierter Erzeugung (Approach 2).\n</li><li>Bei Implementierung von BSW-Generatoren und Build-Pipelines muss festgelegt werden, ob Konfigurationsstrukturen als C-Dateien kompiliert und gelinkt werden oder als direkt flashtaugliche/ladbare Datenblöcke für spezifische Speicherbereiche bereitgestellt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-5cda2965c09bda11", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">SPEM-2.0-basiertes Prozessstruktur- und Dekompositionsdiagramm im Kontext der AUTOSAR-Methodik (AUTOSAR_TR_Methodology). Das Diagramm modelliert die Dekomposition der zusammengesetzten Methodik-Aktivität (Activity) „Do Post Build Loadable Configuration“ in ihre untergeordneten Teilschritte sowie die Zuordnung zweier methodischer Realisierungsansätze.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Im Zentrum steht das zusammengesetzte Aktivitätselement (Activity) „Do Post Build Loadable Configuration“ (dargestellt als abgerundetes Symbol mit Binnen-Piktogrammen). Über Aggregationsbeziehungen mit dem Stereotyp <code>«nesting»</code> (offene Raute an der übergeordneten Aktivität) sind sechs spezifische Prozessaktivitäten (als Blockpfeile nach rechts dargestellt) eingebettet:</p>\n<ul class=\"fig-list\"><li>„Generate BSW Postbuild Configuration Code“\n</li><li>„Compile BSW Configuration Data“\n</li><li>„Link ECU Code during Post-Build Time Loadable“\n</li><li>„Generate BSW Configuration Data Loadable“\n</li><li>„Generate ...“ (am unteren rechten Rand)\n</li><li>„Compile Unconfigured ...“ (am unteren linken Rand)\n</li></ul>\n<p class=\"fig-p\">Zusätzlich sind zwei Notiz-/Kommentarelemente (Note-Symbole mit umgeknickter Ecke) über gestrichelte Verbindungslinien angebunden:</p>\n<ul class=\"fig-list\"><li>„Approach 1: Generate C code“ (zugeordnet zu „Generate BSW Postbuild Configuration Code“)\n</li><li>„Approach 2: Generate loadable data“ (zugeordnet zu „Generate BSW Configuration Data Loadable“)\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt eine statische Schachtelungs- und Strukturhierarchie (Nesting) dar, keine zeitliche Kontrollfluss-Sequenz. Es verdeutlicht zwei alternative bzw. komplementäre Pfade zur Handhabung ladbarer Post-Build-Konfigurationsdaten:</p>\n<ol class=\"fig-list\"><li>Ansatz 1 („Approach 1: Generate C code“): Generierung von C-Quellcode für die Post-Build-Konfiguration („Generate BSW Postbuild Configuration Code“), gefolgt von Kompilierung („Compile BSW Configuration Data“) und Linken zur Post-Build-Zeit („Link ECU Code during Post-Build Time Loadable“).\n</li><li>Ansatz 2 („Approach 2: Generate loadable data“): Direkte Generierung ladbarer Binärdaten („Generate BSW Configuration Data Loadable“), die ohne Neukompilierung des Rumpfcodes in das Steuergerät geladen werden können.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Integratoren und BSW-Tool-Entwickler definiert das Diagramm die methodischen Gestaltungsoptionen für den Post-Build-Loadable-Mechanismus gemäß AUTOSAR-Standard:</p>\n<ul class=\"fig-list\"><li>Trennung zwischen quellcodebasierter Post-Build-Erzeugung (Approach 1) und rein datenbasierter Erzeugung (Approach 2).\n</li><li>Bei Implementierung von BSW-Generatoren und Build-Pipelines muss festgelegt werden, ob Konfigurationsstrukturen als C-Dateien kompiliert und gelinkt werden oder als direkt flashtaugliche/ladbare Datenblöcke für spezifische Speicherbereiche bereitgestellt werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-8b6f8e77d1c78ae9", "to": "FIG-5cda2965c09bda11", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
